-- H-061 A3 (migration 0019; H-060, H-063; docs/design/H-061_BACKGROUND_INVESTIGATOR.md
-- §5, §6, §8, §11-§13; REQ-018, REQ-019, REQ-021): an AI investigation is
-- the stored acting-for scope of one person; its ledger is where the worker
-- and the API meet; what it makes is labelled by the database and capped by
-- it; while app.investigation_id is set the database refuses everything but
-- the tool effects. Each refusal of the design's list comes first, then
-- what must pass: a person approving the AI's ready proposal, the AI's own
-- loop, RLS across organizations.
-- Disposable dt_test_* database only (scripts/run_db_tests.sh). One
-- transaction, rolled back. Generated by scripts/render_db_tests.py.
\set ON_ERROR_STOP 1
BEGIN;
CREATE FUNCTION pg_temp.fail(msg text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('dt.collect', true) = 'on' THEN RAISE WARNING 'FAILED: %', msg;
  ELSE RAISE EXCEPTION 'FAILED: %', msg; END IF;
END $$;
CREATE FUNCTION pg_temp.must_fail(stmt text, state text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE got text; msg text;
BEGIN
  BEGIN
    EXECUTE stmt;
    RAISE EXCEPTION USING ERRCODE = 'P0099'; -- roll the unexpected success back
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE; msg := SQLERRM;
  END;
  IF got = 'P0099' THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s but the statement succeeded: %s', state, stmt));
  ELSIF got <> state THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s but got %s (%s) for: %s', state, got, msg, stmt));
  END IF;
END $$;
-- The statements run one after the other and the deferred checks run as
-- at commit; all of it is rolled back, and the outcome must be state.
CREATE FUNCTION pg_temp.must_fail_at_commit(stmts text[], state text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE got text; msg text; s text;
BEGIN
  BEGIN
    FOREACH s IN ARRAY stmts LOOP
      EXECUTE s;
    END LOOP;
    SET CONSTRAINTS ALL IMMEDIATE;
    RAISE EXCEPTION USING ERRCODE = 'P0099'; -- roll the unexpected success back
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE; msg := SQLERRM;
  END;
  SET CONSTRAINTS ALL DEFERRED;
  IF got = 'P0099' THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s at commit but it committed: %s', state, array_to_string(stmts, '; ')));
  ELSIF got <> state THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s at commit but got %s (%s) for: %s', state, got, msg, array_to_string(stmts, '; ')));
  END IF;
END $$;
-- The statements commit (as far as the deferred checks go) and are rolled back.
CREATE FUNCTION pg_temp.must_commit(stmts text[], what text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE got text; msg text; s text;
BEGIN
  BEGIN
    FOREACH s IN ARRAY stmts LOOP
      EXECUTE s;
    END LOOP;
    SET CONSTRAINTS ALL IMMEDIATE;
    RAISE EXCEPTION USING ERRCODE = 'P0099';
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE; msg := SQLERRM;
  END;
  SET CONSTRAINTS ALL DEFERRED;
  IF got <> 'P0099' THEN
    PERFORM pg_temp.fail(format('%s: expected to commit but got %s (%s)', what, got, msg));
  END IF;
END $$;
CREATE FUNCTION pg_temp.check(ok boolean, what text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF ok IS NOT TRUE THEN PERFORM pg_temp.fail(what); END IF;
END $$;
GRANT EXECUTE ON FUNCTION pg_temp.must_fail_at_commit(text[], text), pg_temp.must_commit(text[], text) TO PUBLIC;
-- The run settings H-047 starts from, within H-060's caps.
CREATE FUNCTION pg_temp.run_config() RETURNS jsonb LANGUAGE sql AS $$
  SELECT '{"horizon":{"value":7,"unit":"day"},"warmup":{"value":0,"unit":"day"},"replications":5,"seed":1,"trace_level":"sampled"}'::jsonb
$$;
GRANT EXECUTE ON FUNCTION pg_temp.run_config() TO PUBLIC;
-- The INSERT of an investigation of model A on version 1, for creator, in
-- mode, from a request, now; overrides replaces any of its columns.
CREATE FUNCTION pg_temp.inv(id text, creator text, mode text, overrides jsonb DEFAULT '{}') RETURNS text LANGUAGE sql AS $$
  SELECT format('INSERT INTO twin.investigations SELECT * FROM jsonb_populate_record(NULL::twin.investigations, %L)',
    jsonb_build_object('id', id, 'organization_id', 'org_01M4YDQK00TA00000000000000', 'model_id', 'mdl_01M4YDQK00TA00000000000001', 'base_version_id', 'mv_01M4YDQK00TA00000000000001', 'mode', mode,
      'source', 'request', 'intent', 'Cut the lead time', 'context', '{}'::jsonb, 'output_locale', 'en', 'research', false,
      'proposal_model', 'muse-spark-1.3', 'planner_model', 'muse-spark-1.3', 'prompt_template_version', 'investigator-0.1.0',
      'objective', CASE mode WHEN 'scenario' THEN '{"metric_path":"/metrics/lead_time_minutes/p50","better":"lower"}'::jsonb END,
      'run_config', CASE mode WHEN 'scenario' THEN pg_temp.run_config() END,
      'run_config_hash', CASE mode WHEN 'scenario' THEN 'sha256:1111111111111111111111111111111111111111111111111111111111111111' END,
      'baseline_name', CASE mode WHEN 'scenario' THEN 'Baseline' END,
      'caps', CASE mode WHEN 'scenario' THEN '{"what_ifs":3,"runs":4,"explanations":4,"steps":14,"minutes":20}'::jsonb
        ELSE '{"what_ifs":1,"runs":0,"explanations":0,"steps":14,"minutes":20}'::jsonb END,
      'status', 'running', 'deadline_at', now() + interval '20 minutes', 'created_by', creator, 'created_at', now()) || overrides)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.inv(text, text, text, jsonb) TO PUBLIC;
-- The INSERT of an investigation's one job, queued.
CREATE FUNCTION pg_temp.ijob(job text, inv text) RETURNS text LANGUAGE sql AS $$
  SELECT format('INSERT INTO twin.jobs(id,organization_id,type,status,payload,investigation_id,max_attempts) VALUES (%L,%L,%L,%L,%L,%L,5)',
    job, 'org_01M4YDQK00TA00000000000000', 'investigation', 'queued', jsonb_build_object('investigation_id', inv, 'request_id', 'req_01M4YDQK00TA00000000000001'), inv)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.ijob(text, text) TO PUBLIC;
-- The worker's claim of a job: the next attempt under the next token.
CREATE FUNCTION pg_temp.claim(job text) RETURNS text LANGUAGE sql AS $$
  SELECT format('UPDATE twin.jobs SET status=''running'', attempt=attempt+1, lease_token=lease_token+1, locked_at=now(), locked_by=''w'', '
      'lease_expires_at=now()+interval ''30 seconds'' WHERE organization_id=%L AND id=%L', 'org_01M4YDQK00TA00000000000000', job)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.claim(text) TO PUBLIC;
-- The INSERT of a call of inv at seq, under (job, token), recorded pending;
-- overrides replaces any of its columns.
CREATE FUNCTION pg_temp.call(inv text, seq int, tool text, job text, token bigint, overrides jsonb DEFAULT '{}') RETURNS text LANGUAGE sql AS $$
  SELECT format('INSERT INTO twin.investigation_tool_calls SELECT * FROM jsonb_populate_record(NULL::twin.investigation_tool_calls, %L)',
    jsonb_build_object('organization_id', 'org_01M4YDQK00TA00000000000000', 'investigation_id', inv, 'seq', seq, 'tool', tool,
      'arguments', CASE tool WHEN 'invalid_call' THEN NULL
        WHEN 'propose_what_if' THEN '{"idea":"Add a second tester at ICT","from_suggestion":null}'::jsonb
        WHEN 'propose_model_edit' THEN '{"idea":"Add a second tester at ICT"}'::jsonb
        WHEN 'finish' THEN '{"outcome":"no_improvement","best_scenario_id":null}'::jsonb
        ELSE '{"proposal_id":"aip_01M4YDQK00TA00000000000041"}'::jsonb END,
      'arguments_hash', CASE WHEN tool <> 'invalid_call' THEN 'sha256:2222222222222222222222222222222222222222222222222222222222222222' END, 'note', 'Testing the bottleneck first.',
      'job_id', job, 'lease_token', token,
      'status', CASE tool WHEN 'invalid_call' THEN 'refused' WHEN 'finish' THEN 'done' ELSE 'pending' END,
      'error', CASE tool WHEN 'invalid_call' THEN '{"code":"UNKNOWN_TOOL","path":""}'::jsonb END,
      'requested_at', now()) || overrides)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.call(text, int, text, text, bigint, jsonb) TO PUBLIC;
-- An UPDATE of the call (inv, seq).
CREATE FUNCTION pg_temp.upd_call(inv text, seq int, change text) RETURNS text LANGUAGE sql AS $$
  SELECT format('UPDATE twin.investigation_tool_calls SET %s WHERE organization_id=%L AND investigation_id=%L AND seq=%s',
    change, 'org_01M4YDQK00TA00000000000000', inv, seq)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.upd_call(text, int, text) TO PUBLIC;
-- An UPDATE of one investigation, one proposal.
CREATE FUNCTION pg_temp.upd_inv(inv text, change text) RETURNS text LANGUAGE sql AS $$
  SELECT format('UPDATE twin.investigations SET %s WHERE organization_id=%L AND id=%L', change, 'org_01M4YDQK00TA00000000000000', inv)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.upd_inv(text, text) TO PUBLIC;
CREATE FUNCTION pg_temp.upd_prop(aip text, change text) RETURNS text LANGUAGE sql AS $$
  SELECT format('UPDATE twin.ai_proposals SET %s WHERE organization_id=%L AND id=%L', change, 'org_01M4YDQK00TA00000000000000', aip)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.upd_prop(text, text) TO PUBLIC;
