-- The INSERT of a run of version 1 (the services' column list): scenario
-- and patch, replications, config and limits as given.
CREATE FUNCTION pg_temp.run(sim text, creator text, scenario text, patch text, replications int DEFAULT 5,
    config jsonb DEFAULT NULL, limits text DEFAULT NULL, config_hash text DEFAULT 'sha256:1111111111111111111111111111111111111111111111111111111111111111', cols text DEFAULT '', vals text DEFAULT '')
  RETURNS text LANGUAGE sql AS $$
  SELECT format('INSERT INTO twin.simulation_runs(id,organization_id,model_id,model_version_id,scenario_id,name,scenario_patch,config,seed,'
      'replications,engine_version,model_hash,effective_model_hash,config_hash,dataset_manifest_hash,dataset_bindings,execution_limits,'
      'created_by,status%s) VALUES (%L,%L,%L,%L,%L,%L,%L,%L,1,%s,%L,%L,%L,%L,%L,%L,%L,%L,%L%s)',
    cols, sim, 'org_01M4YDQK00TA00000000000000', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000001', scenario, 'run', patch, coalesce(config, pg_temp.run_config()), replications,
    'des-go-0.1.0', 'sha256:432750f646ba93a763271505eaf1daa556ef60f2b8d7c97999529683c226120e', 'sha256:432750f646ba93a763271505eaf1daa556ef60f2b8d7c97999529683c226120e', config_hash, 'sha256:4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945', '[]',
    coalesce(limits, '{"wall_timeout_seconds":300,"max_events":10000000,"max_active_entities":100000,"max_entity_visits":10000,"max_trace_events":100000}'),
    creator, 'queued', vals)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.run(text, text, text, text, int, jsonb, text, text, text, text) TO PUBLIC;
