-- ===================================================================
-- Who may do what (H-063): the worker reads both tables, appends calls,
-- records observations and ends its own investigation; the API starts and
-- stops investigations and carries out calls; nobody deletes either; RLS
-- is forced; the worker gains no grant on any existing table.
SELECT pg_temp.check(c.relrowsecurity AND c.relforcerowsecurity, c.relname || ' forces RLS')
  FROM pg_class c WHERE c.oid IN ('twin.investigations'::regclass, 'twin.investigation_tool_calls'::regclass);
SELECT pg_temp.check(has_column_privilege(r, 'twin.' || t, a.attname, 'UPDATE') = (a.attname = ANY (cols)),
    format('%s UPDATE on %s.%s', r, t, a.attname))
  FROM (VALUES
    ('twin_api', 'investigations', ARRAY['status', 'reason', 'finished_at', 'stop_requested_by']),
    ('twin_worker', 'investigations', ARRAY['status', 'reason', 'ai_outcome', 'finished_at']),
    ('twin_api', 'investigation_tool_calls', ARRAY['status', 'proposal_id', 'scenario_id', 'baseline_run_id', 'run_id', 'analysis_id',
      'draft_revision', 'error', 'resolved_at']),
    ('twin_worker', 'investigation_tool_calls', ARRAY['observation', 'observation_hash', 'observed_at'])) AS g(r, t, cols)
  JOIN pg_attribute a ON a.attrelid = ('twin.' || t)::regclass AND a.attnum > 0 AND NOT a.attisdropped;
SELECT pg_temp.check(has_table_privilege(r, 'twin.' || t, p) = ok, format('%s %s on %s', r, p, t)) FROM (VALUES
  ('twin_api', 'investigations', 'SELECT', true), ('twin_api', 'investigations', 'INSERT', true),
  ('twin_api', 'investigations', 'DELETE', false), ('twin_api', 'investigations', 'TRUNCATE', false),
  ('twin_worker', 'investigations', 'SELECT', true), ('twin_worker', 'investigations', 'INSERT', false),
  ('twin_worker', 'investigations', 'DELETE', false),
  ('twin_api', 'investigation_tool_calls', 'SELECT', true), ('twin_api', 'investigation_tool_calls', 'INSERT', false),
  ('twin_api', 'investigation_tool_calls', 'DELETE', false),
  ('twin_worker', 'investigation_tool_calls', 'SELECT', true), ('twin_worker', 'investigation_tool_calls', 'INSERT', true),
  ('twin_worker', 'investigation_tool_calls', 'DELETE', false),
  ('twin_provisioner', 'investigations', 'SELECT', false), ('twin_provisioner', 'investigation_tool_calls', 'SELECT', false),
  ('public', 'investigations', 'SELECT', false), ('public', 'investigation_tool_calls', 'SELECT', false)) AS g(r, t, p, ok);
-- The worker writes no label: its column grants on the labelled tables
-- did not change (0002).
SELECT pg_temp.check(NOT has_column_privilege('twin_worker', 'twin.' || t, c, 'UPDATE'), format('the worker cannot write %s.%s', t, c))
  FROM (VALUES ('ai_proposals', 'investigation_id'), ('ai_proposals', 'investigation_index'), ('ai_proposals', 'applied_draft_revision'),
    ('simulation_runs', 'investigation_id'), ('simulation_runs', 'investigation_slot'), ('ai_analyses', 'investigation_id'),
    ('ai_analyses', 'investigation_index'), ('jobs', 'investigation_id')) AS g(t, c);
SELECT pg_temp.check(count(*) = 21, 'deny_under_investigation on every table it guards: ' || count(*))
  FROM pg_trigger WHERE tgname = 'deny_under_investigation' AND tgenabled = 'O';
SELECT pg_temp.check(NOT has_table_privilege('twin_worker', 'twin.model_drafts', 'SELECT')
    AND NOT has_table_privilege('twin_worker', 'twin.scenarios', 'INSERT'), 'the worker reads no draft and saves no scenario');

-- ===================================================================
-- Starting an investigation: by the API for the scoped user, an owner or
-- editor, running, now, never inside another's scope, with H-060's run
-- settings and caps exactly. Refusals first.
SET LOCAL ROLE twin_api;
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000002', 'scenario'), '42501'); -- not the scoped user
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000004');
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000004', 'scenario'), '42501'); -- a viewer
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000001', 'scenario', o), '55000') FROM unnest(ARRAY[
  '{"status":"finished","reason":"limit_reached","finished_at":"2026-01-01T00:00:00Z"}'::jsonb, -- it starts running
  jsonb_build_object('created_at', now() - interval '1 hour', 'deadline_at', now() - interval '40 minutes') -- back-dated
]) AS o;
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000001', 'scenario', o), '23514') FROM unnest(ARRAY[
  jsonb_build_object('deadline_at', now() + interval '1 hour'), -- 20 minutes, no more
  jsonb_build_object('run_config', pg_temp.run_config() || '{"replications":11}'),
  jsonb_build_object('run_config', pg_temp.run_config() || '{"horizon":{"value":29,"unit":"day"}}'),
  jsonb_build_object('run_config', pg_temp.run_config() || '{"horizon":{"value":40321,"unit":"minute"}}'),
  jsonb_build_object('run_config', pg_temp.run_config() || '{"trace_level":"full"}'),
  jsonb_build_object('run_config', pg_temp.run_config() || '{"warmup":{"value":7,"unit":"day"}}'),
  jsonb_build_object('run_config', pg_temp.run_config() || '{"max_events":1}'),
  jsonb_build_object('run_config', pg_temp.run_config() - 'seed'),
  jsonb_build_object('run_config', pg_temp.run_config() || '{"replications":"5"}'),
  jsonb_build_object('caps', '{"what_ifs":5,"runs":4,"explanations":4,"steps":14,"minutes":20}'::jsonb),
  jsonb_build_object('caps', '{"what_ifs":3,"runs":4,"explanations":4,"steps":20,"minutes":20}'::jsonb),
  jsonb_build_object('objective', '{"metric_path":"/metrics/lead_time_minutes/p50","better":"higher"}'::jsonb),
  jsonb_build_object('planner_model', 'muse-x'),
  jsonb_build_object('intent', ''),
  jsonb_build_object('intent', NULL),
  jsonb_build_object('baseline_name', NULL),
  -- a reused baseline must be a run of the base with no patch and these settings
  jsonb_build_object('baseline_run_id', 'sim_01M4YDQK00TA00000000000099', 'baseline_name', NULL)
]) AS o;
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000001', 'edit', o), '23514') FROM unnest(ARRAY[
  jsonb_build_object('run_config', pg_temp.run_config(), 'run_config_hash', 'sha256:1111111111111111111111111111111111111111111111111111111111111111'),
  jsonb_build_object('objective', '{"metric_path":"/metrics/lead_time_minutes/p50","better":"lower"}'::jsonb),
  jsonb_build_object('caps', '{"what_ifs":3,"runs":4,"explanations":4,"steps":14,"minutes":20}'::jsonb),
  jsonb_build_object('source', 'analysis')
]) AS o;
-- never inside another investigation's acting-for scope
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000008', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000001', 'scenario'), '42501');
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
-- the worker starts none (no INSERT); an investigation needs its job at commit
SET LOCAL ROLE twin_worker;
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000001', 'scenario'), '42501');
SET LOCAL ROLE twin_api;
SELECT pg_temp.must_fail_at_commit(ARRAY[pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000001', 'scenario')], '23514');

-- INV_A1: USR_A's what-ifs, with its job. The request is kept as asked.
SELECT pg_temp.inv('inv_01M4YDQK00TA00000000000001', 'usr_01M4YDQK00TA00000000000001', 'scenario') \gexec
SELECT pg_temp.ijob('job_01M4YDQK00TA00000000000081', 'inv_01M4YDQK00TA00000000000001') \gexec
SELECT pg_temp.check(status = 'running' AND deadline_at = created_at + interval '20 minutes' AND created_at = now() AND reason IS NULL,
    'INV_A1 starts running, with its 20 minutes') FROM twin.investigations WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='inv_01M4YDQK00TA00000000000001';
-- One running per person per organization (409); one job per investigation.
SELECT pg_temp.must_fail(pg_temp.inv('inv_01M4YDQK00TA00000000000009', 'usr_01M4YDQK00TA00000000000001', 'edit'), '23505');
SELECT pg_temp.must_fail(pg_temp.ijob('job_01M4YDQK00TA00000000000099', 'inv_01M4YDQK00TA00000000000001'), '23505');
SELECT pg_temp.must_fail($q$INSERT INTO twin.jobs(id,organization_id,type,status,payload,investigation_id)
  VALUES ('job_01M4YDQK00TA00000000000099','org_01M4YDQK00TA00000000000000','simulation','queued','{}','inv_01M4YDQK00TA00000000000001')$q$, '23514'); -- a job's resource is of its type
-- INV_A2: USR_A2's change to the model; INV_A3: USR_A3's what-ifs.
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000002');
SELECT pg_temp.inv('inv_01M4YDQK00TA00000000000002', 'usr_01M4YDQK00TA00000000000002', 'edit') \gexec
SELECT pg_temp.ijob('job_01M4YDQK00TA00000000000082', 'inv_01M4YDQK00TA00000000000002') \gexec
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000003');
SELECT pg_temp.inv('inv_01M4YDQK00TA00000000000003', 'usr_01M4YDQK00TA00000000000003', 'scenario') \gexec
SELECT pg_temp.ijob('job_01M4YDQK00TA00000000000083', 'inv_01M4YDQK00TA00000000000003') \gexec
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
SET CONSTRAINTS ALL IMMEDIATE; -- each investigation has its job
SET CONSTRAINTS ALL DEFERRED;
-- The request never changes, for any role.
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000001', s), '42501') FROM unnest(ARRAY[
  $q$intent='Something else'$q$, $q$caps='{"what_ifs":3,"runs":4,"explanations":4,"steps":14,"minutes":20}'$q$]) AS s; -- no grant
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000001', s), '55000') FROM unnest(ARRAY[
  $q$intent='Something else'$q$, $q$deadline_at=deadline_at+interval '1 minute', created_at=created_at+interval '1 minute'$q$,
  $q$created_by='usr_01M4YDQK00TA00000000000002'$q$, $q$planner_model='muse-wonder-1.0'$q$, $q$run_config_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222'$q$]) AS s;

-- INV_A5: an investigation whose deadline passed, for USR_A4 (a viewer):
-- back-dated by the schema owner, who is held to the lifecycle, not to the
-- per-role rules.
SELECT pg_temp.inv('inv_01M4YDQK00TA00000000000005', 'usr_01M4YDQK00TA00000000000004', 'scenario',
  jsonb_build_object('created_at', now() - interval '25 minutes', 'deadline_at', now() - interval '5 minutes')) \gexec
SELECT pg_temp.ijob('job_01M4YDQK00TA00000000000085', 'inv_01M4YDQK00TA00000000000005') \gexec

-- ===================================================================
-- The ledger. The worker appends a call under the current lease of the
-- investigation's job, strictly in order, while it runs; refusals first.
SET LOCAL ROLE twin_worker;
SELECT pg_temp.claim('job_01M4YDQK00TA00000000000081') \gexec
SELECT pg_temp.claim('job_01M4YDQK00TA00000000000085') \gexec
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 2), '55000'); -- a stale lease token
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000085', 1), '55000'); -- another investigation's job
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 2, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1), '55000'); -- a skipped seq
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000005', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000085', 1), '55000'); -- after the deadline
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_model_edit', 'job_01M4YDQK00TA00000000000081', 1), '23514'); -- another mode's tool
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1, o), '55000') FROM unnest(ARRAY[
  '{"status":"done","proposal_id":"aip_01M4YDQK00TA00000000000041"}'::jsonb,                                  -- carried out at once
  '{"observation":{"is_error":false},"observation_hash":"sha256:3333333333333333333333333333333333333333333333333333333333333333","observed_at":"2026-01-01T00:00:00Z"}'::jsonb, -- shown already
  '{"status":"refused","error":{"code":"LIMIT_REACHED","path":""}}'::jsonb                  -- refused by the worker
]) AS o;
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'invalid_call', 'job_01M4YDQK00TA00000000000081', 1, '{"status":"pending","error":null}'), '55000');
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'finish', 'job_01M4YDQK00TA00000000000081', 1, '{"status":"pending"}'), '55000');
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'invalid_call', 'job_01M4YDQK00TA00000000000081', 1,
  '{"error":{"code":"LIMIT_REACHED","path":""}}'), '23514'); -- invalid output is UNKNOWN_TOOL or INVALID_ARGUMENTS
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1, '{"note":""}'), '23514');
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1,
  jsonb_build_object('arguments', jsonb_build_object('idea', repeat('x', 9300)))), '23514'); -- arguments over 8 KiB
-- the API records no call
SET LOCAL ROLE twin_api;
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1), '42501');
SET LOCAL ROLE twin_worker;
-- Call 1 of INV_A1: propose_what_if, pending.
SELECT pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1) \gexec
SELECT pg_temp.check(status = 'pending' AND requested_at = now() AND resolved_at IS NULL AND observed_at IS NULL,
    'call 1 is recorded pending') FROM twin.investigation_tool_calls WHERE organization_id='org_01M4YDQK00TA00000000000000' AND investigation_id='inv_01M4YDQK00TA00000000000001' AND seq=1;
-- seq 1 again (two racing inserts of one seq meet the primary key instead)
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 1, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1), '55000');
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000001', 2, 'propose_what_if', 'job_01M4YDQK00TA00000000000081', 1), '55000'); -- call 1 not carried out
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1,
  $q$observation='{"is_error":false}', observation_hash='sha256:3333333333333333333333333333333333333333333333333333333333333333', observed_at=now()$q$), '55000'); -- not carried out yet
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done'$q$), '42501'); -- the worker carries out nothing

-- ===================================================================
-- Carrying out call 1, in INV_A1's acting-for transaction for USR_A: the
-- proposal is labelled by the DEFAULT, indexed by the guard, audited with
-- the AI's mark; the call names it. Refusals first.
SET LOCAL ROLE twin_api;
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000001', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000049', 'usr_01M4YDQK00TA00000000000002', 'scenario'), '42501');           -- for another person
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000049', 'usr_01M4YDQK00TA00000000000001', 'scenario', ',investigation_id', ',NULL'), '42501'); -- unlabelled
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000049', 'usr_01M4YDQK00TA00000000000001', 'scenario', ',investigation_id', $v$,'inv_01M4YDQK00TA00000000000003'$v$), '42501'); -- forged
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000049', 'usr_01M4YDQK00TA00000000000001', 'edit'), '23514');                -- another mode
SELECT pg_temp.prop('aip_01M4YDQK00TA00000000000041', 'usr_01M4YDQK00TA00000000000001', 'scenario', ',investigation_index', ',3') \gexec
SELECT pg_temp.check(investigation_id = 'inv_01M4YDQK00TA00000000000001' AND investigation_index = 1, 'the proposal is labelled and is what-if 1, whatever was asked')
  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000041';
INSERT INTO twin.jobs(id,organization_id,type,status,payload,ai_proposal_id)
  VALUES ('job_01M4YDQK00TA00000000000086','org_01M4YDQK00TA00000000000000','model_proposal','queued','{}','aip_01M4YDQK00TA00000000000041');
SELECT pg_temp.audit('aud_01M4YDQK00TA00000000000011', 'usr_01M4YDQK00TA00000000000001', 'proposal.create', 'ai_proposal', 'aip_01M4YDQK00TA00000000000041',
  '{"investigation_id":"inv_01M4YDQK00TA00000000000001","by_ai":true,"mode":"scenario"}') \gexec
-- What-ifs 2 and 3; a 4th is refused by its cap.
SELECT pg_temp.prop('aip_01M4YDQK00TA00000000000042', 'usr_01M4YDQK00TA00000000000001', 'scenario') \gexec
INSERT INTO twin.jobs(id,organization_id,type,status,payload,ai_proposal_id)
  VALUES ('job_01M4YDQK00TA00000000000087','org_01M4YDQK00TA00000000000000','model_proposal','queued','{}','aip_01M4YDQK00TA00000000000042');
SELECT pg_temp.prop('aip_01M4YDQK00TA00000000000043', 'usr_01M4YDQK00TA00000000000001', 'scenario') \gexec
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000044', 'usr_01M4YDQK00TA00000000000001', 'scenario'), '23514');
SELECT pg_temp.check(array_agg(investigation_index ORDER BY id) = ARRAY[1, 2, 3], 'what-ifs 1, 2 and 3')
  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND investigation_id='inv_01M4YDQK00TA00000000000001';
-- The resolve: in this scope, for this requester, naming what this
-- investigation made. Refusals first.
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done'$q$), '23514');  -- names nothing
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='refused'$q$), '23514'); -- without its error
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done', proposal_id='aip_01M4YDQK00TA00000000000041', scenario_id='scn_01M4YDQK00TA00000000000011'$q$), '23514');
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1,
  $q$status='refused', error='{"code":"BASE_MOVED","path":"","detail":"x"}'$q$), '23514'); -- a closed error
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1,
  $q$status='refused', error='{"code":"MODEL_VERSION_CONFLICT","path":""}'$q$), '23514'); -- an HTTP code is not a tool code
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1,
  $q$observation='{"is_error":false}', observation_hash='sha256:3333333333333333333333333333333333333333333333333333333333333333'$q$), '42501'); -- the API writes no observation
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000001', 'usr_01M4YDQK00TA00000000000002');                                           -- a non-requester
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done', proposal_id='aip_01M4YDQK00TA00000000000041'$q$), '42501');
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000003', 'usr_01M4YDQK00TA00000000000001');                                            -- a forged scope
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done', proposal_id='aip_01M4YDQK00TA00000000000041'$q$), '42501');
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');                                                      -- no scope
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done', proposal_id='aip_01M4YDQK00TA00000000000041'$q$), '42501');
-- a person's proposal is not this investigation's
SELECT pg_temp.prop('aip_01M4YDQK00TA00000000000048', 'usr_01M4YDQK00TA00000000000001', 'scenario') \gexec
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000001', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done', proposal_id='aip_01M4YDQK00TA00000000000048'$q$), '23514');
SELECT pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$status='done', proposal_id='aip_01M4YDQK00TA00000000000041'$q$) \gexec
SELECT pg_temp.check(status = 'done' AND resolved_at = now(), 'call 1 is carried out')
  FROM twin.investigation_tool_calls WHERE organization_id='org_01M4YDQK00TA00000000000000' AND investigation_id='inv_01M4YDQK00TA00000000000001' AND seq=1;
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, s), '55000') FROM unnest(ARRAY[
  $q$status='failed', proposal_id=NULL, error='{"code":"INTERNAL","path":""}'$q$, $q$proposal_id='aip_01M4YDQK00TA00000000000042'$q$]) AS s;
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, s), '55000') FROM unnest(ARRAY[
  $q$arguments='{"idea":"Something else","from_suggestion":null}'$q$, $q$tool='finish'$q$, $q$note='rewritten'$q$,
  $q$requested_at=requested_at - interval '1 minute'$q$, $q$lease_token=7$q$]) AS s;
SET LOCAL ROLE twin_api;

-- ===================================================================
-- The deny triggers: in the acting-for scope the API role may do only the
-- tool effects, whatever its grants.
SELECT pg_temp.must_fail(s, '42501') FROM unnest(ARRAY[
