-- The scope binds every role, the schema owner too: what the API has no
-- grant for is refused by the database itself.
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(s, '42501') FROM unnest(ARRAY[
  $q$UPDATE twin.organizations SET name='x' WHERE id='org_01M4YDQK00TA00000000000000'$q$,
  $q$UPDATE twin.users SET oidc_subject='x' WHERE id='usr_01M4YDQK00TA00000000000001'$q$,
  $q$DELETE FROM twin.investigations WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='inv_01M4YDQK00TA00000000000003'$q$,
  $q$DELETE FROM twin.scenarios WHERE organization_id='org_01M4YDQK00TA00000000000000'$q$,
  $q$DELETE FROM twin.ai_analyses WHERE organization_id='org_01M4YDQK00TA00000000000000'$q$,
  $q$DELETE FROM twin.run_datasets WHERE organization_id='org_01M4YDQK00TA00000000000000'$q$,
  $q$DELETE FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000043'$q$,
  $q$DELETE FROM twin.model_drafts WHERE organization_id='org_01M4YDQK00TA00000000000000'$q$,
  $q$DELETE FROM twin.investigation_tool_calls WHERE organization_id='org_01M4YDQK00TA00000000000000'$q$
]) AS s;
SET LOCAL ROLE twin_api;
-- Audit: only the investigation's own actions, marked as the AI's.
SELECT pg_temp.must_fail(pg_temp.audit('aud_01M4YDQK00TA00000000000019', 'usr_01M4YDQK00TA00000000000001', a, 'ai_proposal', 'aip_01M4YDQK00TA00000000000041', m), '42501') FROM (VALUES
  ('model.publish', '{"investigation_id":"inv_01M4YDQK00TA00000000000001","by_ai":true}'::jsonb),     -- outside the catalogue
  ('proposal.approve', '{"investigation_id":"inv_01M4YDQK00TA00000000000001","by_ai":true}'::jsonb),
  ('proposal.create', '{"mode":"scenario"}'::jsonb),                              -- unmarked
  ('proposal.create', '{"investigation_id":"inv_01M4YDQK00TA00000000000003","by_ai":true}'::jsonb),     -- another investigation
  ('proposal.create', '{"investigation_id":"inv_01M4YDQK00TA00000000000001","by_ai":false}'::jsonb)) AS t(a, m);
-- Reads are fine.
SELECT pg_temp.check(count(*) = 1, 'the scope reads its model') FROM twin.models WHERE organization_id='org_01M4YDQK00TA00000000000000';
-- Without the scope, a person's event never carries the AI's mark.
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.audit('aud_01M4YDQK00TA00000000000019', 'usr_01M4YDQK00TA00000000000001', 'proposal.create', 'ai_proposal', 'aip_01M4YDQK00TA00000000000048',
  '{"investigation_id":"inv_01M4YDQK00TA00000000000001","by_ai":true}'), '42501');
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000049', 'usr_01M4YDQK00TA00000000000001', 'scenario', ',investigation_id', $v$,'inv_01M4YDQK00TA00000000000001'$v$), '42501'); -- a forged label

-- ===================================================================
-- The worker generates what-ifs 1 and 2 (ready) and records what call 1
-- showed the AI, once, under the investigation's job's lease.
SET LOCAL ROLE twin_worker;
SELECT pg_temp.claim(j) FROM unnest(ARRAY['job_01M4YDQK00TA00000000000086','job_01M4YDQK00TA00000000000087']) AS j \gexec
UPDATE twin.ai_proposals SET status='ready', summary='A second tester at ICT.', patch='[{"op":"test","path":"/name","value":"Model A v1"}]',
    patch_hash='sha256:1111111111111111111111111111111111111111111111111111111111111111', validation='{"valid":true,"issues":[]}', confidence=0.9, server_risk_level='low', provider_risk_claim='low', risk_level='low'
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id IN ('aip_01M4YDQK00TA00000000000041','aip_01M4YDQK00TA00000000000042');
UPDATE twin.jobs SET status='completed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id IN ('job_01M4YDQK00TA00000000000086','job_01M4YDQK00TA00000000000087');
SET CONSTRAINTS ALL IMMEDIATE; -- generated with their jobs
SET CONSTRAINTS ALL DEFERRED;
SELECT pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$observation='{"proposal_id":"aip_01M4YDQK00TA00000000000041","status":"ready"}', observation_hash='sha256:3333333333333333333333333333333333333333333333333333333333333333'$q$) \gexec
