SELECT pg_temp.must_fail(pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 1, $q$observation='{"proposal_id":"aip_01M4YDQK00TA00000000000041","status":"invalid"}'$q$), '55000');

