-- Call 2, save_scenario: the AI saves its own ready what-if, and only it:
-- the scenario labelled, the proposal applied (never approved), and the
-- check at commit holds. Refusals first.
SELECT pg_temp.call('inv_01M4YDQK00TA00000000000001', 2, 'save_scenario', 'job_01M4YDQK00TA00000000000081', 1) \gexec
SET LOCAL ROLE twin_api;
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000001', 'usr_01M4YDQK00TA00000000000001');
-- a scenario from a person's proposal, or unlabelled, or for another person
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,source_proposal_id,created_by)
  VALUES ('scn_01M4YDQK00TA00000000000014','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000001','What if','[]','sha256:1111111111111111111111111111111111111111111111111111111111111111',%L,%L)$q$, p, u), e) FROM (VALUES
  ('aip_01M4YDQK00TA00000000000048', 'usr_01M4YDQK00TA00000000000001', '23514'), ('aip_01M4YDQK00TA00000000000041', 'usr_01M4YDQK00TA00000000000002', '42501'), (NULL, 'usr_01M4YDQK00TA00000000000001', '23514')) AS t(p, u, e);
-- applied without its scenario, or with a scenario that is not its patch
SELECT pg_temp.must_fail(pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', $q$status='applied', scenario_id=NULL$q$), '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  $q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,source_proposal_id,created_by)
     VALUES ('scn_01M4YDQK00TA00000000000014','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000001','Another patch','[]','sha256:2222222222222222222222222222222222222222222222222222222222222222','aip_01M4YDQK00TA00000000000041','usr_01M4YDQK00TA00000000000001')$q$,
  pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', $q$status='applied', scenario_id='scn_01M4YDQK00TA00000000000014'$q$)
], '23514');
INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,source_proposal_id,created_by)
  SELECT 'scn_01M4YDQK00TA00000000000011', organization_id, model_id, base_version_id, summary, patch, patch_hash, id, created_by
  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000041';
SELECT pg_temp.check(investigation_id = 'inv_01M4YDQK00TA00000000000001', 'the scenario is labelled') FROM twin.scenarios WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='scn_01M4YDQK00TA00000000000011';
-- never approved, rejected or conflicted in the scope; applied only for its
