SELECT pg_temp.must_fail(pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', s), '42501') FROM unnest(ARRAY[
  $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', scenario_id='scn_01M4YDQK00TA00000000000011'$q$, $q$status='conflicted', decided_by='usr_01M4YDQK00TA00000000000001'$q$]) AS s;
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000001', 'usr_01M4YDQK00TA00000000000002');
SELECT pg_temp.must_fail(pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', $q$status='applied', scenario_id='scn_01M4YDQK00TA00000000000011'$q$), '42501');
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', $q$status='applied', scenario_id='scn_01M4YDQK00TA00000000000011'$q$), '42501');
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000001', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', $q$status='applied', scenario_id='scn_01M4YDQK00TA00000000000011', applied_draft_revision=1$q$), '23514');
SELECT pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', $q$status='applied', scenario_id='scn_01M4YDQK00TA00000000000011'$q$) \gexec
SELECT pg_temp.audit('aud_01M4YDQK00TA00000000000012', 'usr_01M4YDQK00TA00000000000001', 'proposal.apply', 'ai_proposal', 'aip_01M4YDQK00TA00000000000041',
  '{"investigation_id":"inv_01M4YDQK00TA00000000000001","by_ai":true,"scenario_id":"scn_01M4YDQK00TA00000000000011"}') \gexec
SELECT pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 2, $q$status='done', scenario_id='scn_01M4YDQK00TA00000000000011'$q$) \gexec
SET CONSTRAINTS ALL IMMEDIATE; -- the scenario is its applied proposal's one effect
SET CONSTRAINTS ALL DEFERRED;
SELECT pg_temp.check(status = 'applied' AND decided_by IS NULL AND decided_at IS NULL, 'applied, never decided')
  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000041';
-- applied is final: never approved or rejected afterwards, by anyone.
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', s), '55000') FROM unnest(ARRAY[
  $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001'$q$, $q$status='rejected', decided_by='usr_01M4YDQK00TA00000000000001'$q$, $q$summary='rewritten'$q$]) AS s;
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(pg_temp.upd_prop('aip_01M4YDQK00TA00000000000041', s), '55000') FROM unnest(ARRAY[
  $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001'$q$, $q$investigation_index=2$q$]) AS s;
-- A person may still approve the AI's ready proposal (what-if 2): the
-- scenario is the person's, with no label, and the check holds (TEST-008).
SET LOCAL ROLE twin_api;
-- ...but not with the AI's label on the scenario
SELECT pg_temp.must_fail(format($q$INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,source_proposal_id,created_by,investigation_id)
  VALUES ('scn_01M4YDQK00TA00000000000014','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000001','x','[]','sha256:1111111111111111111111111111111111111111111111111111111111111111','aip_01M4YDQK00TA00000000000042','usr_01M4YDQK00TA00000000000001','inv_01M4YDQK00TA00000000000001')$q$), '42501');
INSERT INTO twin.scenarios(id,organization_id,model_id,base_version_id,name,patch,patch_hash,source_proposal_id,created_by)
  SELECT 'scn_01M4YDQK00TA00000000000013', organization_id, model_id, base_version_id, summary, patch, patch_hash, id, 'usr_01M4YDQK00TA00000000000001'
  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000042';
SELECT pg_temp.upd_prop('aip_01M4YDQK00TA00000000000042', $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', scenario_id='scn_01M4YDQK00TA00000000000013'$q$) \gexec
SET CONSTRAINTS ALL IMMEDIATE; -- the person's scenario is the approved proposal's one effect
SET CONSTRAINTS ALL DEFERRED;
SELECT pg_temp.check(s.investigation_id IS NULL AND p.status = 'approved' AND p.decided_by = 'usr_01M4YDQK00TA00000000000001',
    'a person approved the AI''s ready proposal; the scenario is the person''s')
  FROM twin.scenarios s JOIN twin.ai_proposals p ON p.organization_id = s.organization_id AND p.id = s.source_proposal_id
  WHERE s.organization_id='org_01M4YDQK00TA00000000000000' AND s.id='scn_01M4YDQK00TA00000000000013';

