SET LOCAL ROLE twin_worker;
SELECT pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 3, $q$observation='{"run_id":"sim_01M4YDQK00TA00000000000014"}', observation_hash='sha256:3333333333333333333333333333333333333333333333333333333333333333'$q$) \gexec
SELECT pg_temp.call('inv_01M4YDQK00TA00000000000001', 4, 'explain_results', 'job_01M4YDQK00TA00000000000081', 1, '{"arguments":{"run_id":"sim_01M4YDQK00TA00000000000014","question":null}}') \gexec
