SELECT pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 4, $q$status='done', analysis_id='ana_01M4YDQK00TA00000000000011'$q$) \gexec
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.ana('ana_01M4YDQK00TA00000000000015', 'usr_01M4YDQK00TA00000000000001', 'sim_01M4YDQK00TA00000000000012', 'sim_01M4YDQK00TA00000000000011', ',investigation_id', $v$,'inv_01M4YDQK00TA00000000000001'$v$), '42501');

-- ===================================================================
-- A 15th step is refused (INV_A3: 14 refused invalid calls, each observed,
-- written by the owner, who is held to the sequence).
SET LOCAL ROLE twin_owner;
DO $$
BEGIN
  FOR i IN 1..14 LOOP
    EXECUTE pg_temp.call('inv_01M4YDQK00TA00000000000003', i, 'invalid_call', 'job_01M4YDQK00TA00000000000083', 1);
    EXECUTE pg_temp.upd_call('inv_01M4YDQK00TA00000000000003', i, $q$observation='{"is_error":true}', observation_hash='sha256:3333333333333333333333333333333333333333333333333333333333333333'$q$);
  END LOOP;
END $$;
SET LOCAL ROLE twin_worker;
SELECT pg_temp.claim('job_01M4YDQK00TA00000000000083') \gexec
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000003', 15, 'invalid_call', 'job_01M4YDQK00TA00000000000083', 1), '23514');

