], '23514'); -- a proposal that was not applied as an edit

-- ===================================================================
-- Ending. Refusals first: the worker only for its own reasons and only in
-- the transaction that ends the job; the API only a person's stop (the
-- requester or an owner, in their own name), role_lost once the role is
-- gone, time_limit 2 minutes after the deadline with no worker on it.
SET LOCAL ROLE twin_worker;
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000001', $q$status='finished', reason='limit_reached'$q$), '55000'); -- its job still runs
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000001', s), '42501') FROM unnest(ARRAY[
  $q$status='stopped', reason='stopped_by_person'$q$, $q$status='stopped', reason='role_lost'$q$]) AS s;
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000001', $q$status='stopped', reason='stopped_by_person', stop_requested_by='usr_01M4YDQK00TA00000000000001'$q$), '42501');
SET LOCAL ROLE twin_api;
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000003');                                                     -- another editor
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', $q$status='stopped', reason='stopped_by_person', stop_requested_by='usr_01M4YDQK00TA00000000000003'$q$), '42501');
SELECT pg_temp.acting('', 'usr_01M4YDQK00TA00000000000001');
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', $q$status='stopped', reason='stopped_by_person', stop_requested_by='usr_01M4YDQK00TA00000000000002'$q$), '42501');
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', s), '42501') FROM unnest(ARRAY[
  $q$status='finished', reason='finished_by_ai', ai_outcome='no_improvement'$q$, $q$status='stopped', reason='ai_failed'$q$]) AS s;
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', $q$status='stopped', reason='role_lost'$q$), '55000');  -- USR_A2 is still an editor
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', $q$status='stopped', reason='time_limit'$q$), '55000'); -- before its deadline
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000005', $q$status='stopped', reason='time_limit'$q$), '55000'); -- a worker runs it
-- An owner stops USR_A2's investigation; a stop is final.
SELECT pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', $q$status='stopped', reason='stopped_by_person', stop_requested_by='usr_01M4YDQK00TA00000000000001'$q$) \gexec
SELECT pg_temp.check(finished_at = now() AND stop_requested_by = 'usr_01M4YDQK00TA00000000000001', 'an owner stopped INV_A2')
  FROM twin.investigations WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='inv_01M4YDQK00TA00000000000002';
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', $q$status='finished', reason='limit_reached'$q$), '55000');
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(pg_temp.upd_inv('inv_01M4YDQK00TA00000000000002', $q$status='finished', reason='limit_reached', stop_requested_by=NULL$q$), '55000');
-- After a stop, the worker records no call and the database refuses every
-- labelled write in its scope.
SET LOCAL ROLE twin_worker;
SELECT pg_temp.claim('job_01M4YDQK00TA00000000000082') \gexec
SELECT pg_temp.must_fail(pg_temp.call('inv_01M4YDQK00TA00000000000002', 1, 'propose_model_edit', 'job_01M4YDQK00TA00000000000082', 1), '55000');
SET LOCAL ROLE twin_api;
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000002', 'usr_01M4YDQK00TA00000000000002');
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000046', 'usr_01M4YDQK00TA00000000000002', 'edit'), '55000');
SELECT pg_temp.acting('inv_01M4YDQK00TA00000000000005', 'usr_01M4YDQK00TA00000000000004');                                         -- after its deadline
SELECT pg_temp.must_fail(pg_temp.prop('aip_01M4YDQK00TA00000000000046', 'usr_01M4YDQK00TA00000000000004', 'scenario'), '55000');
-- The worker ends INV_A2's job after the API's stop: completed with it.
SET LOCAL ROLE twin_worker;
SELECT pg_temp.acting('', '');
UPDATE twin.jobs SET status='completed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000082';
