UPDATE twin.memberships SET role='viewer' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND user_id='usr_01M4YDQK00TA00000000000003';
SET LOCAL ROLE twin_api;
SELECT pg_temp.upd_inv('inv_01M4YDQK00TA00000000000003', $q$status='stopped', reason='role_lost'$q$) \gexec
SELECT pg_temp.check(count(*) = 2, 'INV_A3 and INV_A5 ended by the API') FROM twin.investigations
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id IN ('inv_01M4YDQK00TA00000000000003','inv_01M4YDQK00TA00000000000005') AND status = 'stopped' AND finished_at = now();

-- An investigation's job completes or is cancelled only with its end; a
