SELECT pg_temp.inv('inv_01M4YDQK00TA00000000000007', 'usr_01M4YDQK00TA00000000000004', 'edit') \gexec
SELECT pg_temp.ijob('job_01M4YDQK00TA00000000000092', 'inv_01M4YDQK00TA00000000000007') \gexec
