SELECT pg_temp.claim('job_01M4YDQK00TA00000000000091') \gexec
SELECT pg_temp.must_fail_at_commit(ARRAY[
  $q$UPDATE twin.jobs SET status='completed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000091'$q$
], '55000');
UPDATE twin.jobs SET status='failed', locked_at=NULL, locked_by=NULL, lease_expires_at=NULL,
    error='{"code":"AI_PROVIDER_UNAVAILABLE","message":"the AI provider is unavailable","retryable":false}'
