SELECT pg_temp.check(status = 'stopped' AND reason = 'ai_failed' AND finished_at = now(), 'INV_A6 followed its failed job')
  FROM twin.investigations WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='inv_01M4YDQK00TA00000000000006';

-- The worker's Finish of INV_A1: the finish call (done, the last), the
-- job, then the investigation with the AI's claim and investigation.end.
SELECT pg_temp.upd_call('inv_01M4YDQK00TA00000000000001', 4, $q$observation='{"analysis_id":"ana_01M4YDQK00TA00000000000011"}', observation_hash='sha256:3333333333333333333333333333333333333333333333333333333333333333'$q$) \gexec
SELECT pg_temp.must_fail_at_commit(ARRAY[pg_temp.call('inv_01M4YDQK00TA00000000000001', 5, 'finish', 'job_01M4YDQK00TA00000000000081', 1)], '55000'); -- finish ends it
SELECT pg_temp.call('inv_01M4YDQK00TA00000000000001', 5, 'finish', 'job_01M4YDQK00TA00000000000081', 1) \gexec
